{
  "understanding": {
    "purpose": "Help passengers find a flight and quickly check its destination, departure times, gate, and current status.",
    "reading": "Readers locate a flight or destination, then scan across the row; scheduled and estimated times need to be easy to compare. Wrapping is most useful where another cell in the same row already makes the row taller.",
    "groups": [
      "Flight and Destination identify the departure.",
      "Scheduled and Estimated are paired times and should have similar widths for comparison.",
      "Gate and Status describe where to go and what is happening."
    ],
    "keep_intact": [
      "Individual flight numbers, times, gate codes, and single-word statuses.",
      "The Scheduled and Estimated headers."
    ],
    "may_wrap": [
      "Multiword destinations at word boundaries, preferably without splitting flight identifiers in the same row.",
      "Multiword statuses at word boundaries; a status can wrap within a row already made taller by its destination."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [78, 133, 98, 94, 55, 99],
      "idea": "Balance destination and status space while keeping flight identifiers on one line and giving the paired time columns comparable widths."
    },
    {
      "name": "B",
      "widths": [66, 155, 98, 94, 55, 89],
      "idea": "Favor destination legibility, accepting more wrapping in flight identifiers and multiword statuses."
    },
    {
      "name": "C",
      "widths": [78, 105, 98, 94, 55, 127],
      "idea": "Give status messages nearly their full one-line width, accepting more destination wrapping while keeping flight identifiers intact."
    }
  ]
}
